export function validateSharedCard(card){
  if(!card||!Number.isSafeInteger(card.id)||card.id<1000000||typeof card.name!=='string'||!card.name.trim()||card.name.length>80||typeof card.cardName!=='string'||!card.cardName.trim()||card.cardName.length>120||!['SSR','SR','R'].includes(card.rarity)||!['緑','赤','青'].includes(card.attribute))throw Error('追加カードの情報が正しくありません');
  if(typeof card.image!=='string'||card.image.length>250000||!/^data:image\/jpeg;base64,[A-Za-z0-9+/]+=*$/.test(card.image))throw Error('カード画像が正しくありません');
  const skillDetails={};
  for(const type of ['passive','active','unique']){
    const list=card.skillDetails?.[type];if(!Array.isArray(list)||list.length>12)throw Error('スキルが正しくありません');
    skillDetails[type]=list.map(s=>{if(typeof s.name!=='string'||!s.name.trim()||s.name.length>100||typeof s.description!=='string'||s.description.length>2000)throw Error('スキルの情報が正しくありません');return{name:s.name,description:s.description,requiresRear:s.requiresRear===true||/増援|後衛/.test(s.description),positionCheck:s.positionCheck===true||s.name.includes('エントリー'),cost:null};});
  }
  return{id:card.id,name:card.name,cardName:card.cardName,rarity:card.rarity,attribute:card.attribute,image:card.image,initialStats:{},attackerType:null,linkBonus:null,sourceUrl:null,dataStatus:'partial',userAdded:true,skillDetails,skills:Object.fromEntries(Object.entries(skillDetails).map(([key,list])=>[key,list.map(s=>s.name+'\n'+s.description).join('\n')||null]))};
}
export function createSharedCards(config,request=fetch){
  async function rpc(name,body={}){if(!config?.enabled)throw Error('共有保存先が未設定です');const response=await request(config.url+'/rest/v1/rpc/'+name,{method:'POST',headers:{apikey:config.publishableKey,'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const data=await response.json();if(!response.ok)throw Error(data.message?.includes('duplicate_card')?'同じ名前・カード名のカードが登録されています。':data.message?.includes('rate_limit')?'少し待ってから登録してください。':'カード共有の設定がまだ反映されていないか、通信に失敗しました。');return data;}
  return {enabled:config?.enabled===true,async list(){const data=await rpc('builder_card_list');if(!Array.isArray(data)||data.length>5000)throw Error('追加カードを読み込めません');return data.map(validateSharedCard);},async add(card){const value=validateSharedCard({...card,id:1000000});delete value.id;return validateSharedCard(await rpc('builder_card_add',{p_card:value}));}};
}
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountCardForm(root,onSave,existing){
  let image='',alive=true,busy=false;
  root.innerHTML=`<h2>全員の図鑑にカードを追加</h2><p>名前・画像・スキルを確認して登録してください。戦力は各利用者が手持ちで入力します。</p><form id="newCardForm"><label>キャラ名<input name="name" required maxlength="80"></label><label>カード名<input name="cardName" required maxlength="120"></label><label>レア度<select name="rarity">${['SSR','SR','R'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>属性<select name="attribute">${['緑','赤','青'].map(s=>`<option>${s}</option>`).join('')}</select></label><label>カード画像<input type="file" accept="image/png,image/jpeg,image/webp" required aria-label="追加カードの画像"></label><div class="image-edit-preview" hidden><img alt="追加カードのプレビュー"></div><p class="muted">スキルは1行に1つ。「スキル名 | 説明」の形で入力します。不明なら空欄にできます。例：スタンエントリー | 増援として参加した時に発動</p>${[['passive','パッシブ'],['active','アクティブ'],['unique','ユニーク']].map(([key,label])=>`<label>${label}スキル<textarea name="${key}" maxlength="25000" rows="3"></textarea></label>`).join('')}<p role="status" class="new-card-status"></p><button class="primary" type="submit">全員の図鑑に登録</button></form>`;
  const form=root.querySelector('form'),status=root.querySelector('.new-card-status'),submit=form.querySelector('button');
  form.querySelector('input[type=file]').onchange=async e=>{let bitmap;busy=true;submit.disabled=true;image='';try{const file=e.target.files[0];if(!file)return;if(file.size>20000000)throw Error('画像は20MB以下にしてください');bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#242034';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const value=canvas.toDataURL('image/jpeg',.7);if(value.length>250000)throw Error('画像を小さくして選び直してください');if(!alive)return;image=value;root.querySelector('.image-edit-preview').hidden=false;root.querySelector('img').src=image;status.textContent='画像を確認してください。登録後に位置調整できます。';}catch(err){if(alive)status.textContent=err.message;}finally{bitmap?.close();busy=false;if(alive)submit.disabled=false;}};
  form.onsubmit=async e=>{e.preventDefault();e.stopPropagation();if(busy)return;busy=true;submit.disabled=true;try{if(!image)throw Error('カード画像を選んでください');const values=new FormData(form),name=values.get('name').trim(),cardName=values.get('cardName').trim(),rarity=values.get('rarity'),attribute=values.get('attribute');if(existing.some(c=>c.name.replace(/\s/g,'')===name.replace(/\s/g,'')&&c.cardName.replace(/\s/g,'')===cardName.replace(/\s/g,'')&&c.rarity===rarity))throw Error('同じカードが図鑑にあります');const skillDetails={};for(const type of ['passive','active','unique'])skillDetails[type]=values.get(type).split('\n').map(s=>s.trim()).filter(Boolean).map(line=>{const split=line.indexOf('|');return{name:(split<0?line:line.slice(0,split)).trim(),description:split<0?'':line.slice(split+1).trim()};});const card={name,cardName,rarity,attribute,image,skillDetails};validateSharedCard({...card,id:1000000});status.textContent='共有の図鑑に登録中…';await onSave(card);}catch(err){if(alive)status.textContent=err.message;}finally{busy=false;if(alive)submit.disabled=false;}};
  return()=>{alive=false;};
}
